def eval_rpn(tokens):
    st = []
    for t in tokens:
        if t in '+-*/':
            b = st.pop(); a = st.pop()
            if t == '+': st.append(a+b)
            elif t == '-': st.append(a-b)
            elif t == '*': st.append(a*b)
            else: st.append(int(a/b))
        else:
            st.append(int(t))
    return st[0]

def eval_rpn(tokens):
    import operator as op
    fns = {'+':op.add, '-':op.sub, '*':op.mul}
    st = []
    for t in tokens:
        if t in fns:
            b = st.pop(); a = st.pop()
            st.append(fns[t](a, b))
        elif t == '/':
            b = st.pop(); a = st.pop()
            st.append(int(a / b))
        else:
            st.append(int(t))
    return st[0]

