class MyQueue:
    def __init__(self):
        self.sin = []
        self.sout = []
    def push(self, x):
        self.sin.append(x)
    def _shift(self):
        if not self.sout:
            while self.sin:
                self.sout.append(self.sin.pop())
    def pop(self):
        self._shift()
        return self.sout.pop()
    def peek(self):
        self._shift()
        return self.sout[-1]
    def empty(self):
        return not self.sin and not self.sout

