def decode_string(s):
    def dfs(i):
        out = []; num = 0
        while i < len(s):
            if s[i].isdigit():
                num = num * 10 + int(s[i])
            elif s[i] == '[':
                sub, i = dfs(i + 1)
                out.append(sub * num)
                num = 0
            elif s[i] == ']':
                return ''.join(out), i + 1
            else:
                out.append(s[i])
            i += 1
        return ''.join(out), i
    return dfs(0)[0]

